n  & img {\n    width: 100%;\n    height: 100%;\n    max-height: 100px;\n    object-fit: contain;\n  }\n}\n\n.dialog__subject-text {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.dialog__subject-text-title {\n  @include fonts($defaultColor, 20px, 400);\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 1;\n  -webkit-box-orient: vertical;\n}\n\n.dialog__subject-text-price {\n  @include fonts($defaultColor, 16px, 400);\n}\n\n.cross__dialog {\n      width: 20px;\n    height: 20px;\n    position: absolute;\n    top: 5px;\n    right: 5px;\n    cursor: pointer;\n}\n\n\n.message__list {\n  padding: 20px 0;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  background-color: #f5f5f5;\n  border-radius: 7px 7px 0 0;\n  overflow-y: auto;\n  height: 300px;\n  align-items: center;\n}\n\n.messages__item-date {\n  @include fonts($defaultColor, 14px, 400);\n  padding: 5px;\n  background-color: $headerTopBorder;\n  border-radius: 10px;\n}\n\n.message__item {\n  padding: 5px;\n  margin: 0 10px;\n  display: flex;\n  gap: 3px;\n  max-width: 90%;\n\n}\n.message__item-text {\n  word-break: break-word;\n  white-space: break-spaces;\n  padding-bottom: 5px;\n}\n\n.message-self {\n  align-self: flex-end;\n  background-color: $userSearchBg;\n  @include fonts($defaultColor, 18px, 400);\n  border-radius: 10px 10px 0 10px;\n}\n\n.message-any {\n  align-self: flex-start;\n  background-color: $gray;\n  @include fonts($defaultColor, 18px, 400);\n  border-radius: 10px 10px 10px 0;\n}\n\n.message__item-time {\n  display: flex;\n  @include fonts($defaultColor, 10px, 400);\n  align-items: flex-end;\n}\n\n.message__input {\n  display: flex;\n  width: 100%;\n  gap: 5px;\n  position: relative;\n  padding: 15px;\n  border: 1px solid $gray;\n  border-radius: 7px;\n}\n\n#id_message_send_input {\n  resize: none;\n  caret-color: #00ad64;\n  @include fonts($defaultColor, 18px, 400);\n  flex: 1 1 auto;\n  height: 100%;\n\n  textarea:focus {\n    border: none;\n    box-shadow: inset 0 0 5px #719ece;\n    outline: none;\n  }\n}\n\n.message__input-send {\n  display: flex;\n  align-self: center;\n  background: none;\n  width: 24px;\n  height: 24px;\n  cursor: pointer;\n  transition: .4s ease-in;\n\n  \n  &[disabled] {\n    transition: .4s ease-out;\n    cursor: no-drop;\n    fill: $gray;\n  }\n}\n",".dialog__subject {\n  display: flex;\n  gap: 20px;\n  align-items: center;\n  border: 1px solid #D4D4D4;\n  border-radius: 7px;\n  margin-bottom: 10px;\n  position: relative;\n  height: 110px;\n}\n\n.dialog__subject-img {\n  padding-left: 10px;\n  flex: 0 0 120px;\n}\n.dialog__subject-img img {\n  width: 100%;\n  height: 100%;\n  max-height: 100px;\n  object-fit: contain;\n}\n\n.dialog__subject-text {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.dialog__subject-text-title {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 20px;\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 1;\n  -webkit-box-orient: vertical;\n}\n\n.dialog__subject-text-price {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n}\n\n.cross__dialog {\n  width: 20px;\n  height: 20px;\n  position: absolute;\n  top: 5px;\n  right: 5px;\n  cursor: pointer;\n}\n\n.message__list {\n  padding: 20px 0;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  background-color: #f5f5f5;\n  border-radius: 7px 7px 0 0;\n  overflow-y: auto;\n  height: 300px;\n  align-items: center;\n}\n\n.messages__item-date {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  padding: 5px;\n  background-color: #bdd4e2;\n  border-radius: 10px;\n}\n\n.message__item {\n  padding: 5px;\n  margin: 0 10px;\n  display: flex;\n  gap: 3px;\n  max-width: 90%;\n}\n\n.message__item-text {\n  word-break: break-word;\n  white-space: break-spaces;\n  padding-bottom: 5px;\n}\n\n.message-self {\n  align-self: flex-end;\n  background-color: #CFE6FE;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 18px;\n  border-radius: 10px 10px 0 10px;\n}\n\n.message-any {\n  align-self: flex-start;\n  background-color: #D4D4D4;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 18px;\n  border-radius: 10px 10px 10px 0;\n}\n\n.message__item-time {\n  display: flex;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 10px;\n  align-items: flex-end;\n}\n\n.message__input {\n  display: flex;\n  width: 100%;\n  gap: 5px;\n  position: relative;\n  padding: 15px;\n  border: 1px solid #D4D4D4;\n  border-radius: 7px;\n}\n\n#id_message_send_input {\n  resize: none;\n  caret-color: #00ad64;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 18px;\n  flex: 1 1 auto;\n  height: 100%;\n}\n#id_message_send_input textarea:focus {\n  border: none;\n  box-shadow: inset 0 0 5px #719ece;\n  outline: none;\n}\n\n.message__input-send {\n  display: flex;\n  align-self: center;\n  background: none;\n  width: 24px;\n  height: 24px;\n  cursor: pointer;\n  transition: 0.4s ease-in;\n}\n.message__input-send[disabled] {\n  transition: 0.4s ease-out;\n  cursor: no-drop;\n  fill: #D4D4D4;\n}","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);"]}2;\n$a